mapper.sql:
FROM sys_notice_user nu
INNER JOIN sys_notice n ON n.notice_id = nu.notice_id
WHERE nu.user_id = #{userId}
  AND nu.is_del = 0
  AND n.is_del = 0
  AND n.is_send = 1
  AND (n.expire_time IS NULL OR n.expire_time > NOW())

    AND n.notice_title LIKE CONCAT('%', #{noticeTitle}, '%')


    AND n.notice_type = #{noticeType}


    AND nu.is_read = #{readState}

mapper.select:
SELECT nu.user_id, u.user_account, u.user_name, u.dept_id, nu.is_read AS read_state, nu.read_time FROM sys_notice_user nu LEFT JOIN sys_user u ON u.user_id = nu.user_id AND u.is_del = 0 WHERE nu.notice_id = #{noticeId} AND nu.is_del = 0
AND nu.is_read = #{readState}
ORDER BY nu.is_read ASC, nu.read_time DESC, nu.create_time DESC
